const body = $input.first().json.body || $input.first().json;

const reservaId            = body.reserva_id            || '';
const tokenOnboarding      = body.token_onboarding      || '';
const telefoneTitular      = body.telefone_titular       || '';
const nomeTitular          = body.nome_titular           || '';
const documentoTitular     = body.documento_titular      || '';
const nacionalidadeTitular = body.nacionalidade_titular  || 'Brasileira';
const acompanhantesJson    = body.acompanhantes_json     || '[]';
const veiculoPlaca         = body.veiculo_placa          || '';
const veiculoModelo        = body.veiculo_modelo         || '';
const veiculoCor           = body.veiculo_cor            || '';
const aceiteIp             = body.aceite_ip              || '';
const aceiteUserAgent      = body.aceite_user_agent      || '';
const aceiteTimestamp      = body.aceite_timestamp       || new Date().toISOString();
const aceiteHash           = body.aceite_hash_contrato   || '';
const preenchidoEm         = body.preenchido_em          || new Date().toISOString();

// Formata telefone: +5511999999999 → 5511999999999
const telefoneE164 = telefoneTitular.replace(/^\+/, '');
const primeiroNome = nomeTitular.split(' ')[0] || '';

if (!reservaId || !documentoTitular) {
  throw new Error('Dados obrigatórios ausentes: reserva_id ou documento_titular');
}

return [{ json: {
  reserva_id:            reservaId,
  token_onboarding:      tokenOnboarding,
  telefone_e164:         telefoneE164,
  primeiro_nome:         primeiroNome,
  documento_titular:     documentoTitular,
  nacionalidade_titular: nacionalidadeTitular,
  acompanhantes_json:    acompanhantesJson,
  veiculo_placa:         veiculoPlaca,
  veiculo_modelo:        veiculoModelo,
  veiculo_cor:           veiculoCor,
  aceite_ip:             aceiteIp,
  aceite_user_agent:     aceiteUserAgent,
  aceite_timestamp:      aceiteTimestamp,
  aceite_hash_contrato:  aceiteHash,
  preenchido_em:         preenchidoEm
} }];

// Puxa os dados que o nó "Sheets Read LOG" acabou de ler
const log = $input.first().json;
const dataCheckinRaw = log.data_checkin || '';

// Pega o valor atual de urgência (que deve estar vazio)
let urgenciaFinal = log.urgencia || '';

if (dataCheckinRaw) {
  const hoje = new Date();
  hoje.setHours(0, 0, 0, 0);

  const checkin = new Date(dataCheckinRaw);
  checkin.setHours(0, 0, 0, 0);

  const diasRestantes = Math.round((checkin - hoje) / (1000 * 60 * 60 * 24));

  // Se o check-in for HOJE, marcamos como "urgente"
  if (diasRestantes === 0) {
    urgenciaFinal = 'urgente';
  }
}

// Passa adiante os dados originais, forçando a atualização APENAS do campo "urgencia"
return [{
  json: {
    ...log,
    urgencia: urgenciaFinal
  }
}];

