// Pega o canal da reserva (lido do LOG)
const canal = ($('Sheets Read LOG').first().json.canal || '').toLowerCase();

// Se for Airbnb, para aqui e não repassa nada adiante.
if (canal.includes('airbnb')) {
  return [];
}

// Nao é Airbnb, repassa o item sem alterar.
return $input.all();

const log = $('Sheets Read LOG').first().json;

const trim = function(s) { return String(s || '').trim(); };
const normalizaData = function(d) { return trim(d).slice(0, 10); };

const formatarDataBR = function(iso) {
  var d = normalizaData(iso);
  if (!d || d.length < 10) return d;
  return d.slice(8,10) + '/' + d.slice(5,7) + '/' + d.slice(0,4);
};

return [{
  json: {
    fluxo:                'checkin',
    reserva_id:           trim(log.reserva_id),
    unidade_nome:         trim(log.unidade_nome),
    primeiro_nome:        trim(log.hospede_nome).split(' ')[0] || 'Hóspede',
    hospede_nome:         trim(log.hospede_nome),
    numero_evolution:     trim(log.hospede_id).replace(/^\+/, ''),
    data_checkin:         formatarDataBR(log.data_checkin),
    data_checkout:        formatarDataBR(log.data_checkout),
    arquivos_para_enviar: ['instrucoes_checkin.md', 'regras.md', 'endereco_e_senhas.md'],
    flag_envio:           'msg_checkin_enviada'
  }
}];

// Dados da reserva (LOG)
const log = $('Sheets Read LOG').first().json;

// Dados da portaria (CAD_UNIDADES_STAYS)
const u = $('Sheets: Busca Portaria').first().json;

// Dados do onboarding preenchido (ONBOARDING_HOSPEDES)
const ob = $('Sheets: Busca Docs Hóspede').first().json;

// Helpers
function norm(s) { return String(s ?? '').trim().toLowerCase(); }
function dataBR(d) {
  const s = String(d ?? '').trim().slice(0, 10);
  const p = s.split('-');
  return p.length === 3 ? `${p[2]}/${p[1]}/${p[0]}` : s;
}
function soDigitos(s) { return String(s ?? '').replace(/\D/g, ''); }
function separaUnidade(nome) {
  const m = String(nome ?? '').trim().match(/^(\D+?)\s*(\d.*)$/);
  if (m) return { edificio: m[1].trim(), unidade: m[2].trim() };
  return { edificio: String(nome ?? '').trim(), unidade: '' };
}

const { edificio, unidade } = separaUnidade(log.unidade_nome);
const portariaId   = soDigitos(u.portaria_id || '');
const portariaNome = u.portaria_nome || 'Portaria';
const horaIn       = u.hora_checkin  || '';
const horaOut      = u.hora_checkout || '';
const garagem      = u.garagem       || '';
const gSim         = norm(garagem) === 'sim';

// Hóspedes: titular + acompanhantes
let acompanhantes = [];
try { acompanhantes = JSON.parse(ob.acompanhantes_json || '[]'); } catch(e) {}

const pessoas = [
  { nome: log.hospede_nome || '', doc: ob.documento_titular || '' },
  ...(Array.isArray(acompanhantes) ? acompanhantes : []),
].filter(p => p.nome || p.doc);

const listaHospedes = pessoas
  .map((p, i) => `${i + 1}. ${p.nome}${p.doc ? ' - ' + p.doc : ''}`)
  .join('\n');

// Veículo
const temPlaca = !!String(ob.veiculo_placa || '').trim();
const linhaGaragem = `Vaga de garagem: (${gSim ? 'X' : ' '}) Sim (${gSim ? ' ' : 'X'}) Não`;
let blocoVeiculo;
if (temPlaca) {
  const desc = [ob.veiculo_modelo, ob.veiculo_cor].filter(Boolean).join(' ');
  blocoVeiculo = `Veículo autorizado:${desc ? ' ' + desc : ''}\nPlaca: ${ob.veiculo_placa}`;
} else {
  blocoVeiculo = `Veículo autorizado: não informado\nPlaca: -`;
}

const mensagem =
`⚡ ENTRADA URGENTE — MESMO DIA

Prezados,

Informamos que a unidade ${unidade || log.unidade_nome}, no Edifício ${edificio}, estará locada por temporada no período de ${dataBR(log.data_checkin)} a ${dataBR(log.data_checkout)}, com os seguintes hóspedes autorizados:

👤 Hóspedes autorizados (${pessoas.length} ${pessoas.length === 1 ? 'pessoa' : 'pessoas'})

${listaHospedes}

🕒 Horários da hospedagem
Check-in: a partir das ${horaIn}
Check-out: até ${horaOut}

🚗 Veículo / Garagem
${linhaGaragem}
${blocoVeiculo}

Atenciosamente,
[NOME DA EMPRESA]`;

return [{ json: {
  numero_portaria: portariaId,
  mensagem,
  reserva_id:    log.reserva_id,
  unidade_nome:  log.unidade_nome,
  portaria_nome: portariaNome,
  tem_portaria:  !!portariaId,
}}];
